function activityDetails(array $row):string {
    $details=(string)$row['details'];if($row['action']==='backup.restored')$details=preg_replace('/; oporavak [a-f0-9]{32}$/','',$details)??$details;$id=$row['entity_id']??null;$action=$row['action'];$parts=[];
    if($id!==null)$parts[]=match(true){str_starts_with($action,'order.'),str_starts_with($action,'payment.')=>'Narud�ba #'.$id,str_starts_with($action,'stock_exit.')=>'Izlaz robe #'.$id,$action==='stock.adjusted',$action==='product.saved'=>'Artikal #'.$id,str_starts_with($action,'mail.')=>'Poruka #'.$id,default=>'Zapis #'.$id};
    if($action==='stock.adjusted'&&preg_match('/^(-?\d+)\s*(.*)$/s',$details,$quantity))return implode('  ',array_merge($parts,['Koli�ina: '.$quantity[1].' kom.','Obrazlo�enje: '.($quantity[2]?:'Nije navedeno')]));
    $json=json_decode($details,true);
    if(is_array($json)&&in_array($action,['order.delivery_prepared','delivery.saved'],true)){
        $labels=['method'=>'Na�in dostave','courier'=>'Kurir','cost'=>'Tro�ak KM','payer'=>'Dostavu pla�a','terms'=>'Uslovi','tracking'=>'Broj po�iljke','note'=>'Obrazlo�enje','name'=>'Naziv','active'=>'Dostupno kupcima'];
        foreach($json as $key=>$value){if(!isset($labels[$key])||!is_scalar($value))continue;if($key==='payer')$value=($value==='customer'?'kupac':($value==='sender'?'prodavac':$value));if($key==='active')$value=$value?'Da':'Ne';if($value!=='')$parts[]=$labels[$key].': '.$value;}
    }else{
        if($action==='order.status')$details=preg_replace_callback('/\b(new|preparing|shipped|delivered|completed|cancelled|returned|handed_over)\b/',static fn($m)=>orderStatus($m[1]),$details)??$details;
        if($action==='stock_exit.created')foreach(exitReasons() as $key=>$label)$details=preg_replace('/\b'.preg_quote($key,'/').'\b/',$label,$details)??$details;
        if(trim($details)!=='')$parts[]=str_replace(' -> ','  ',$details);
    }
    return implode('  ',$parts)?:'Promjena je uredno evidentirana.';
}
